from pathlib import Path

def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

write('.dockerignore', '.git\n.env\n.venv\n__pycache__\n.pytest_cache\n.mypy_cache\n.ruff_cache\ndata\nartifacts\n')
write('.env.example', 'APP_NAME=Kalshi Weather ML Service\nAPP_ENV=development\nLOG_LEVEL=INFO\nAPI_PREFIX=/v1\n\n# Generate each with: python scripts/generate_api_key.py\nML_SERVICE_API_KEYS=replace-with-a-long-random-key\nADMIN_API_KEY=replace-with-a-separate-long-random-admin-key\n\nDATABASE_URL=sqlite:///./data/weather_ml.sqlite3\nREDIS_URL=redis://redis:6379/0\nTASK_ALWAYS_EAGER=true\n\nMODEL_STORE_URI=./artifacts\nACTIVE_MODEL_CACHE_SECONDS=60\nMIN_DATA_QUALITY_SCORE=0.70\nMAX_INPUT_DATA_AGE_SECONDS=7200\nMIN_TRAINING_ROWS=250\n\nRATE_LIMIT_REQUESTS=240\nRATE_LIMIT_WINDOW_SECONDS=60\nCORS_ORIGINS=[]\nTRUSTED_HOSTS=["*"]\n\nOPEN_METEO_ARCHIVE_URL=https://archive-api.open-meteo.com/v1/archive\nOPEN_METEO_HISTORICAL_FORECAST_URL=https://historical-forecast-api.open-meteo.com/v1/forecast\nNWS_API_URL=https://api.weather.gov\nHTTP_USER_AGENT=kalshi-weather-ml-service/1.0 contact@example.com\nHTTP_TIMEOUT_SECONDS=45\n\nS3_ENDPOINT_URL=\nAWS_REGION=us-east-1\nAWS_ACCESS_KEY_ID=\nAWS_SECRET_ACCESS_KEY=\n\nPROMETHEUS_ENABLED=true\nAUTO_CREATE_TABLES=true\n')
